/**
 * Build → post hand-over.
 *
 * pptxgenjs writes every object with a unique name `fd:<n>` (its `objectName`). The manifest says, per
 * slide and per object name, what post/ has to patch in the generated OOXML: text bodies, gradient
 * fills, line properties, geometry adjustments, shadows, hyperlinks, SVG blips and group wrapping.
 * At the very end post/ renames every `fd:<n>` to the Figma layer name.
 *
 * XML fragments stored here are complete, schema-ordered elements generated by build/ (pure strings).
 */
import type { TextBodySpec } from './textBody';

/** Axis-aligned rectangle, EMU. */
export interface EmuRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Target of a hyperlink, resolved into a slide relationship by post/. */
export type LinkTarget =
  | { type: 'url'; url: string }
  /** 1-based slide number (target part `slide<N>.xml`). */
  | { type: 'slide'; slideNumber: number };

interface ManifestObjectBase {
  /** Unique object name written by pptxgenjs (`fd:<n>`). */
  name: string;
  /** Figma layer name (unescaped). Replaces `name` at the end of post-processing. */
  layerName: string;
  /** Axis-aligned bounds of the (rotated) object, EMU — used for group extents. */
  bounds: EmuRect;
  /** Index into `SlideManifest.links`: click action on the whole object. */
  link: number | null;
  /** `<a:effectLst>` appended at the end of `<p:spPr>`; null = none. */
  effectLst: string | null;
}

export interface TextObject extends ManifestObjectBase {
  kind: 'text';
  /** Replaces the whole `<p:txBody>` written by pptxgenjs. */
  body: TextBodySpec;
}

export interface ShapeObject extends ManifestObjectBase {
  kind: 'shape';
  /** Replaces the fill element that follows `<a:prstGeom>` (gradients); null keeps pptxgenjs' fill. */
  fill: string | null;
  /** Replaces pptxgenjs' `<a:ln>` (always written: stroke or `<a:ln><a:noFill/></a:ln>`). */
  ln: string;
  /** Replaces `<a:prstGeom>` (exact roundRect `adj`); null keeps pptxgenjs' geometry. */
  geometry: string | null;
}

export interface ImageObject extends ManifestObjectBase {
  kind: 'image';
  /** Replaces `<a:prstGeom>` (roundRect clip); null keeps pptxgenjs' geometry. */
  geometry: string | null;
  /** SVG asset added as `asvg:svgBlip` next to the raster blip; null = none. */
  svgAssetId: string | null;
}

export type ManifestObject = TextObject | ShapeObject | ImageObject;

/** A group to wrap into `<p:grpSp>`. Members are contiguous in z-order. */
export interface ManifestGroup {
  /** `fd:<n>` name given to the `<p:grpSp>`. */
  name: string;
  layerName: string;
  /** Names of the direct members (objects or other groups), back to front. */
  members: string[];
  /** Union of the members' bounds, EMU (written as off/ext = chOff/chExt). */
  bounds: EmuRect;
  link: number | null;
}

export interface SlideManifest {
  /** 1-based slide number (`ppt/slides/slide<N>.xml`). */
  number: number;
  /** Figma frame name (becomes `<p:cSld name>`). */
  name: string;
  objects: ManifestObject[];
  /** Groups in post-order (a nested group comes before the group that contains it). */
  groups: ManifestGroup[];
  links: LinkTarget[];
}

export interface PackageMeta {
  title: string;
  subject: string;
  author: string;
  company: string;
  application: string;
  /** ISO 8601 timestamp without milliseconds (`2026-01-31T12:00:00Z`). */
  timestamp: string;
}

export interface BuildManifest {
  slides: SlideManifest[];
  /** SVG sources by asset id (only the ones referenced by an `ImageObject.svgAssetId`). */
  svgAssets: Record<string, Uint8Array>;
  meta: PackageMeta;
}
